# Section 4.1: table P3-T1, the routing counts by team, version, random order and capacity.
r = ROUT[ROUT["capacity_label"].isin(L.T_CAPS)].copy()
cri = CELLS3[L.lam_eq(CELLS3["lambda"], 0.057) & CELLS3["capacity_label"].isin(L.T_CAPS)][["seed", "team", "version", "capacity_label",
      "criterion_1_share_expert_right_policy_1_wrong", "criterion_1_share_expert_wrong_policy_1_right"]]
cri = cri[cri["team"].isin(["A", "C"])].assign(routing=lambda x: x["team"].map({"A": "AB", "C": "C"})).drop(columns="team")
r = r.merge(cri, on=["routing", "version", "seed", "capacity_label"], how="left")
cols = ["routing", "version", "seed", "router_table", "capacity_label", "K", "load", "n_eligible", "n_reviewed", "n_to_classifier", "n_team_c_test"] + \
       [f"n_slot_{i}" for i in range(10)] + ["ties_experts_tied_resolved_by_fewest", "ties_experts_tied_resolved_by_slot", "ties_best_expert_equal_to_classifier",
       "criterion_1_share_expert_right_policy_1_wrong", "criterion_1_share_expert_wrong_policy_1_right"]
r["capacity_label"] = pd.Categorical(r["capacity_label"], L.T_CAPS, ordered=True)
T1 = r[cols].sort_values(["routing", "capacity_label", "version", "seed"])
V.show(T1, 'P3-T1.df1', hide=['router_table'], rename={'seed': 'random order', 'capacity_label': 'capacity', 'K': 'review places', 'load': 'share of review places used', 'n_eligible': 'alerts on which a reviewer outscores the classifier', 'n_reviewed': 'alerts sent to a reviewer', 'n_to_classifier': 'alerts decided by the classifier', 'n_team_c_test': "alerts left to the classifier under team C's rule", 'n_slot_0': 'alerts to member 1', 'n_slot_1': 'alerts to member 2', 'n_slot_2': 'alerts to member 3', 'n_slot_3': 'alerts to member 4', 'n_slot_4': 'alerts to member 5', 'n_slot_5': 'alerts to member 6', 'n_slot_6': 'alerts to member 7', 'n_slot_7': 'alerts to member 8', 'n_slot_8': 'alerts to member 9', 'n_slot_9': 'alerts to member 10', 'ties_experts_tied_resolved_by_fewest': 'equal scores between reviewers, settled by fewest alerts so far', 'ties_experts_tied_resolved_by_slot': 'equal scores between reviewers, settled by member order', 'ties_best_expert_equal_to_classifier': "best reviewer's score equal to the classifier's", 'criterion_1_share_expert_right_policy_1_wrong': 'reviewer right, classifier wrong (share of reviewed alerts)', 'criterion_1_share_expert_wrong_policy_1_right': 'reviewer wrong, classifier right (share of reviewed alerts)'}, index_names={}, column_names={}, values={'routing': {'AB': 'teams A and B', 'C': 'team C'}}, index={}, cells=[], empty_cells=True); L.save(T1, "P3-T1a_routing.csv")
